/*
 * Stock firmware v1.13: the functions and variables our code uses.
 *
 * Part of hackai-mpk. Licensed under GPL-3.0-or-later.
 *
 * Functions are resolved by the linker from config/symbols.csv (build/mods/
 * stock.ld, generated by tools/build_mod.py), so a name here must exist there.
 * The stock firmware is built with IAR, which follows the AAPCS like GCC.
 * RAM variables are fixed addresses found during the analysis, see docs/.
 */
#ifndef HK_STOCK_H
#define HK_STOCK_H

#include <stdint.h>

/* --- Display (docs/display.md, docs/menus.md) ----------------------------- */

/* Draws a string with a font; invert = 1 for highlighted text. */
void print_LCD_APP(uint16_t x, uint16_t y, const char *str, const uint8_t *font,
                   uint8_t invert);
void framebuffer_clear_APP(void);
void menu_title_rule_APP(void);

/* Menu font: byte 0 = character width, byte 1 = row height (10 x 10). */
#define FONT_MENU ((const uint8_t *)0x08025810)

/* --- Menus (docs/menus.md) ------------------------------------------------ */

#define UI_SCREEN    (*(volatile uint8_t *)0x20004DA8) /* current screen id */
#define UI_EDIT      (*(volatile uint8_t *)0x20004DAE) /* 0 choose entry, 1 edit value */
#define UI_CURSOR    (*(volatile uint8_t *)0x20004DAF) /* entry number */
#define UI_STATE     (*(volatile uint8_t *)0x20004DA6) /* 1 temporary, 2 normal, 3 screensaver */

#define SCREEN_GLOBAL 0x16

/* 64-bit tick counter (20 us) and time of the last activity (screensaver). */
#define TICKS_NOW           ((volatile uint32_t *)0x20004CB8)
#define TICKS_LAST_ACTIVITY ((volatile uint32_t *)0x20004BF0)

void transpose_apply_POSSIBLE_APP(void);

/* --- Pads (docs/pads.md) ------------------------------------------------- */

#define SCREEN_PAD_EDIT 0x19
#define PAD_EDITING (*(volatile uint8_t *)0x20004E03) /* pad shown in the pad edit menu */

/* Per-pad state while playing: 12 bytes per pad, 8 pads per bank; byte 1 is
 * the MIDI channel used by the pad's current note. */
#define PAD_STATE      0x200045D8u
#define PAD_STATE_BANK 0x60u
#define PAD_STATE_SIZE 0x0Cu

void pad_edit_menu_draw_APP(uint8_t pad);

/* Pad LEDs (docs/leds.md): the 8 physical pads show the current bank. */
#define PAD_BANK        (*(volatile uint8_t *)0x20004DFE) /* 0 = A, 1 = B */
#define PAD_SPECIAL_MODE (*(volatile uint8_t *)0x20004DCE) /* pads show something else */
#define PAD_STATE_LIT   0 /* byte of the pad state record: 1 = lit by the stock code */
void pad_led_show_APP(uint8_t pad, uint8_t lit);

/* --- Current program (docs/programs.md) ----------------------------------- */

#define PROGRAM ((volatile uint8_t *)0x20000668)
#define PROG_PAD_CHANNEL   0x10  /* 0-15 */
#define PROG_PAD_AFTERTOUCH 0x11 /* 0 Off, 1 Chan, 2 Poly */
#define PROG_MIDI_CHANNEL  0x12  /* 0-15 */
#define PROG_TRANSPOSE     0x14  /* 0-24, 12 = none */
#define PROG_TPRT          0x15  /* 0-1 */
#define PROG_TAPS          0x1C  /* 2-4 */

/* Pad records: 7 bytes per pad, bank A then B (docs/programs.md). */
#define PROG_PADS          0x37
#define PAD_RECORD(pad) (&PROGRAM[PROG_PADS + (pad) * 7])
enum { PAD_NOTE, PAD_CC, PAD_PC, PAD_MODE, PAD_TOGGLE, PAD_ON_COLOUR, PAD_OFF_COLOUR };

/* --- MIDI (docs/midi.md) -------------------------------------------------- */

/* DIN IN: 128-byte ring filled by USART1_IRQHandler. */
uint16_t din_rx_count_APP(void);
uint8_t din_rx_read_APP(void);
#define DIN_IN_PAUSED (*(volatile uint8_t *)0x20004E0A) /* poll skipped while set */

/* MIDI byte stream to USB-MIDI packets; returns 1 when *packet is complete.
 * Packet word: CIN|cable (bits 31-24), then the MIDI bytes (23-0). */
uint8_t midi_parser_feed_APP(uint8_t *state, uint8_t byte, uint32_t *packet);
#define MIDI_PARSER_DIN ((uint8_t *)0x20004C78)

/* A complete message: status, data1, data2. */
void midi_message_handle_APP(uint8_t *message);

/* USB-MIDI events for the host: 128-byte ring of 4-byte packets. */
#define USB_STATE        (*(volatile uint8_t *)(0x200011B8 + 0x112)) /* 3 = configured */
#define USB_CONFIGURED   3
#define USB_IN_RING      ((volatile uint8_t *)0x200048B0)
#define USB_IN_WRITE     (*(volatile uint16_t *)0x20004D86)

/* DIN OUT: 64-byte ring, sent by DMA from the main loop. No overflow check. */
void din_tx_queue_APP(uint8_t count, const uint8_t *bytes);
#define DIN_TX_SIZE  64
#define DIN_TX_WRITE (*(volatile uint8_t *)0x20004DFA)
#define DIN_TX_READ  (*(volatile uint8_t *)0x20004DFB)

/* --- Flash (docs/updater.md for the controller) --------------------------- */

#define FLASH_OK 4  /* return value of the erase/program functions */

void flash_unlock(void);
void flash_lock(void);
void flash_flag_clear(uint32_t flags);
uint8_t flash_sector_erase_APP(uint32_t address);
uint8_t flash_word_program_APP(volatile uint32_t *address, uint32_t value);

#define FLASH_FLAGS_ALL 0x34  /* PRGMERR | EPPERR | ODF, as the stock code clears */

#endif
